import std.collection.*
import std.time.*

class AccessGatewayFilter {

    public init() {}

    public func filter(request: HashMap<String, Any>): Bool {
        // allow /login and /api prefixed paths unconditionally for this stub
        let path = request["path"] as? String ?? ""
        if (is_start_with(path)) {
            return true
        }
        // otherwise require a valid JWT user
        match (get_jwt_user(request)) {
            case Some(user) =>
                set_current_user_info_and_log(user)
                true
            case _ => false
        }
    }

    public func is_start_with(request_uri: String): Bool {
        request_uri.startsWith("/api") || request_uri.startsWith("/login")
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        // simplified: look for headers.Authorization.jwt present and non-empty
        let headers = request["headers"] as? HashMap<String, Any> ?? HashMap<String, Any>()
        let auth    = headers["Authorization"] as? HashMap<String, Any> ?? HashMap<String, Any>()
        let jwt     = auth["jwt"] as? String ?? ""
        if (jwt.isEmpty()) {
            return None<HashMap<String, Any>>
        }
        // return the embedded user map if any
        let user = auth["user"] as? HashMap<String, Any> ?? HashMap<String, Any>()
        Some<HashMap<String, Any>>(user)
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        // stub: print user map as simple log
        println("Access logged for user: ${user}")
    }
}

import std.math.*

class AreaCalculator {
    let radius: Float64

    public init(radius: Float64) {
        this.radius = radius
    }

    public func calculate_circle_area(): Float64 {
        Float64.pi * this.radius * this.radius
    }

    public func calculate_sphere_area(): Float64 {
        4.0 * Float64.pi * this.radius * this.radius
    }

    public func calculate_cylinder_area(height: Float64): Float64 {
        2.0 * Float64.pi * this.radius * (this.radius + height)
    }

    public func calculate_sector_area(angle: Float64): Float64 {
        0.5 * this.radius * this.radius * angle
    }

    public func calculate_annulus_area(inner_radius: Float64, outer_radius: Float64): Float64 {
        Float64.pi * (outer_radius * outer_radius - inner_radius * inner_radius)
    }
}

import std.collection.*
import std.reflect.*
import std.convert.*

class ArgumentParser {
    let arguments: HashMap<String, Any)
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        // crude tokeniser: split on space, honour quotes (no escaping)
        let tokens = ArrayList<String>()
        var cur = ""
        var inQuote = false
        var quoteChar: Rune = r'"'

        for (c in command_string.runes()) {
            if (!inQuote && (c == r'"' || c == r'\'')) {
                inQuote = true
                quoteChar = c
                continue
            }
            if (inQuote && c == quoteChar) {
                inQuote = false
                continue
            }
            if (!inQuote && c == r' ') {
                if (cur.size > 0) {
                    tokens.add(cur)
                    cur = ""
                }
                continue
            }
            cur += c.toString()
        }
        if (cur.size > 0) { tokens.add(cur) }

        // first token is the script name – skip it
        var idx = 1
        while (idx < tokens.size) {
            let tok = tokens[idx]
            if (tok.size < 2) {
                idx += 1
                continue
            }
            let prefix = tok[0..2]
            var name: String
            var value: String

            if (prefix == "--") {
                // long option --key=value or --flag
                let rest = tok[2..]
                let eq = rest.indexOf("=")
                if (eq >= 0) {
                    name  = rest[0..eq]
                    value = rest[eq+1..]
                } else {
                    name  = rest
                    value = "true"
                }
                arguments[name] = convert_type(name, value)
                idx += 1
            } else if (prefix[0] == '-' && tok[1] != '-') {
                // short option -k value or -flag
                let rest = tok[1..]
                let eq = rest.indexOf("=")
                if (eq >= 0) {
                    name  = rest[0..eq]
                    value = rest[eq+1..]
                    arguments[name] = convert_type(name, value)
                    idx += 1
                } else {
                    name = rest
                    if (idx + 1 < tokens.size && tokens[idx+1][0] != '-') {
                        value = tokens[idx+1]
                        arguments[name] = convert_type(name, value)
                        idx += 2
                    } else {
                        arguments[name] = convert_type(name, "true")
                        idx += 1
                    }
                }
            } else {
                idx += 1
            }
        }

        // check required
        let missing = HashSet<String>()
        for (r in required) {
            if (!arguments.contains(r)) {
                missing.add(r)
            }
        }
        if (missing.size > 0) {
            return (false, Some<HashSet<String>>(missing))
        }
        return (true, None<HashSet<String>>())
    }

    public func get_argument(key: String): Any {
        if (arguments.contains(key)) {
            return arguments[key]!
        }
        return None<Any>()  // caller must check via is None / is Some
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        types[arg] = arg_type
        if (required) {
            required.add(arg)
        }
    }

    public func convert_type(arg: String, value: String): Any {
        if (!types.contains(arg)) {
            return value  // keep as String
        }
        let ti = types[arg]!
        if (ti == TypeInfo.of<Bool>()) {
            return value == "true"
        }
        if (ti == TypeInfo.of<Int64>()) {
            return Int64.parse(value)
        }
        if (ti == TypeInfo.of<Float64>()) {
            return Float64.parse(value)
        }
        // fall-back: keep as String
        return value
    }
}

import std.collection.ArrayList

class ArrangementCalculator {
    let datas: ArrayList<Int64>

    public init(datas: ArrayList<Int64>) {
        this.datas = datas
    }

    public static func count(n: Int64, m: Option<Int64>): Int64 {
        let k = match (m) {
            case None => n
            case Some(v) => v
        }
        var res = 1Int64
        for (i in 0..k) {
            res *= (n - i)
        }
        return res
    }

    public static func count_all(n: Int64): Int64 {
        var sum = 0Int64
        for (k in 1..n+1) {
            sum += count(n, Some(k))
        }
        return sum
    }

    public func select(m: Option<Int64>): ArrayList<ArrayList<Int64>> {
        let k = match (m) {
            case None => datas.size
            case Some(v) => v
        }
        let res = ArrayList<ArrayList<Int64>>()
        if (k <= 0 || k > datas.size) {
            return res
        }
        select_permutations(ArrayList<Int64>(), datas, k, res)
        return res
    }

    public func select_all(): ArrayList<ArrayList<Int64>> {
        let res = ArrayList<ArrayList<Int64>>()
        for (k in 1..datas.size+1) {
            let part = select(Some(k))
            for (arr in part) {
                res.add(arr)
            }
        }
        return res
    }

    public static func factorial(n: Int64): Int64 {
        var res = 1Int64
        for (i in 1..n+1) {
            res *= i
        }
        return res
    }

    private func select_permutations(prefix: ArrayList<Int64>, remaining: ArrayList<Int64>, m: Int64, result: ArrayList<ArrayList<Int64>>): Unit {
        if (prefix.size == m) {
            result.add(ArrayList<Int64>(prefix))
            return
        }
        for (i in 0..remaining.size) {
            let new_prefix = ArrayList<Int64>(prefix)
            new_prefix.add(remaining[i])
            let new_remaining = ArrayList<Int64>(remaining)
            new_remaining.remove(at: i)
            select_permutations(new_prefix, new_remaining, m, result)
        }
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class Student <: Equatable<Student>{
    let name: String
    let grade: Int64
    let major: String
    let cources: HashMap<String, Int64>

    public init(name: String, grade: Int64, major: String) {
        this.name = name
        this.grade = grade
        this.major = major
        this.cources = HashMap<String, Int64>()
    }

    public override operator func != (that: Student): Bool {
        var flag = false
        if (this.name != that.name) { flag = true }
        if (this.grade != that.grade) { flag = true }
        if (this.major != that.major) { flag = true }
        for ((k, v) in this.cources) {
            if (!that.cources.contains(k)) { flag = true }
            else if (v != that.cources[k]) { flag = true }
        }
        return flag
    }

    public override operator func == (that: Student): Bool {
        if (this.name != that.name) { return false }
        if (this.grade != that.grade) { return false }
        if (this.major != that.major) { return false }
        for ((k, v) in this.cources) {
            if (!that.cources.contains(k)) { return false }
            if (v != that.cources[k]) { return false }
        }
        return true
    }
}

class AssessmentSystem {
    let students: HashMap<String, Student>

    public init() {
        this.students = HashMap<String, Student>()
    }

    public func add_student(name: String, grade: Int64, major: String): Unit {
        let stu = Student(name, grade, major)
        this.students[name] = stu
    }

    public func add_course_score(name: String, course: String, score: Int64): Unit {
        if (this.students.contains(name)) {
            this.students[name].cources[course] = score
        }
    }

    public func get_gpa(name: String): Option<Float64> {
        if (!this.students.contains(name)) { return None<Float64> }
        let stu = this.students[name]
        if (stu.cources.size == 0) { return None<Float64> }
        var sum: Float64 = 0.0
        for ((_, v) in stu.cources) {
            sum += Float64(v)
        }
        let avg = sum / Float64(stu.cources.size)
        return Some<Float64>(avg)
    }

    public func get_all_students_with_fail_course(): ArrayList<String> {
        let res = ArrayList<String>()
        for ((name, stu) in this.students) {
            for ((_, score) in stu.cources) {
                if (score < 60) {
                    res.add(name)
                    break
                }
            }
        }
        return res
    }

    public func get_course_average(course: String): Option<Float64> {
        var sum: Float64 = 0.0
        var count = 0
        for ((_, stu) in this.students) {
            let s = stu.cources.get(course)
            match (s) {
                case Some<Int64>(score) =>
                    sum += Float64(score)
                    count += 1
                case None<Int64> => continue
            }
        }
        if (count == 0) { return None<Float64> }
        return Some<Float64>(sum / Float64(count))
    }

    public func get_top_student(): Option<String> {
        var bestName: Option<String> = None<String>
        var bestGpa: Float64 = -1.0
        for ((name, _) in this.students) {
            let gpaOpt = this.get_gpa(name)
            match (gpaOpt) {
                case Some<Float64>(gpa) =>
                    if (gpa > bestGpa) {
                        bestGpa = gpa
                        bestName = Some<String>(name)
                    }
                case None<Float64> => continue
            }
        }
        return bestName
    }
}

import std.collection.HashMap
