        this.inventory.get(title).getOrElse(0)
    }
}

import std.collection.ArrayList

class BoyerMooreSearch {

    let text: String
    let pattern: String
    let textLen: Int64
    let patLen: Int64

    public init(text: String, pattern: String) {
        this.text = text
        this.pattern = pattern
        this.textLen = text.size
        this.patLen = pattern.size
    }

    public func match_in_pattern(char: String): Int64 {
        var idx = this.patLen - 1
        while (idx >= 0) {
            if (this.pattern[idx] == char[0]) {
                return idx
            }
            idx -= 1
        }
        return -1
    }

    public func mismatch_in_text(currentPos: Int64): Int64 {
        var i = this.patLen - 1
        while (i >= 0) {
            if (currentPos + i >= this.textLen) {
                return i
            }
            if (this.text[currentPos + i] != this.pattern[i]) {
                return i
            }
            i -= 1
        }
        return -1
    }

    public func bad_character_heuristic(): ArrayList<Int64> {
        let res = ArrayList<Int64>([])
        var s = 0
        while (s <= this.textLen - this.patLen) {
            let mismatch = this.mismatch_in_text(s)
            if (mismatch == -1) {
                res.add(s)
                s += 1
            } else {
                let char = String(this.text[s + mismatch])
                let k = this.match_in_pattern(char)
                if (k == -1) {
                    s += mismatch + 1
                } else {
                    s += max(1, mismatch - k)
                }
            }
        }
        return res
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.convert.Parsable.*

public func precedence(op: String): Int64 {
    match (op) {
        case "+" | "-" => 1
        case "*" | "/" => 2
        case "^"       => 3
        case _         => 0
    }
}

public func apply_operator(operand_stack: ArrayList<Float64>,
                           operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
    let op = operator_stack.remove(at: operator_stack.size - 1)
    let right = operand_stack.remove(at: operand_stack.size - 1)
    let left  = operand_stack.remove(at: operand_stack.size - 1)
    let res = operators.get(op).getOrThrow()(left, right)
    operand_stack.add(res)
    (operand_stack, operator_stack)
}

public func calculate(expression: String): Option<Float64> {
    let numBuffer: ArrayList<Rune> = ArrayList<Rune>()
    var operand_stack = ArrayList<Float64>()
    var operator_stack = ArrayList<String>()

    for (ch in expression.runes()) {
        if (ch >= r'0' && ch <= r'9' || ch == r'.') {
            numBuffer.add(ch)
            continue
        }
        if (numBuffer.size > 0) {
            let numStr = String(numBuffer.toRuneArray())
            let parsed = Float64.parse(numStr)
            if (parsed is None) { return None<Float64> }
            operand_stack.add((parsed as Some<Float64>).value)
            numBuffer.clear()
        }
        let op = String([ch])
        if (operators.contains(op)) {
            while (operator_stack.size > 0 &&
                   precedence(operator_stack[operator_stack.size - 1]) >= precedence(op)) {
                let tmp = apply_operator(operand_stack, operator_stack)
                operand_stack = tmp[0]
                operator_stack = tmp[1]
            }
            operator_stack.add(op)
        } else if (ch == r' ') {
            continue
        } else {
            return None<Float64>
        }
    }
    if (numBuffer.size > 0) {
        let numStr = String(numBuffer.toRuneArray())
        let parsed = Float64.parse(numStr)
        if (parsed is None) { return None<Float64> }
        operand_stack.add((parsed as Some<Float64>).value)
    }
    while (operator_stack.size > 0) {
        let tmp = apply_operator(operand_stack, operator_stack)
        operand_stack = tmp[0]
        operator_stack = tmp[1]
    }
    if (operand_stack.size != 1) { return None<Float64> }
    Some<Float64>(operand_stack[0])
}

