class ChandrasekharSieve {
    let n: Int64
    var primes: ArrayList<Int64> = ArrayList<Int64>()

    public init(n: Int64) {
        this.n = n
        this.primes = generate_primes()
    }

    public func generate_primes(): ArrayList<Int64> {
        if (n < 2) {
            return ArrayList<Int64>()
        }
        var sieve = ArrayList<Bool>(Array(n + 1, item: true))
        sieve[0] = false
        sieve[1] = false
        for (i in 2..Int64(sqrt(Float64(n))) + 1) {
            if (sieve[i]) {
                for (j in i * i..n + 1 : i) {
                    sieve[j] = false
                }
            }
        }
        var res = ArrayList<Int64>()
        for (k in 2..n + 1) {
            if (sieve[k]) {
                res.add(Int64(k))
            }
        }
        return res
    }

    public func get_primes(): ArrayList<Int64> {
        return primes
    }
}

