class Classroom {
    let id: Int64
    let courses: ArrayList<Course>

    public init(id: Int64) {
        this.id = id
        this.courses = ArrayList<Course>()
    }

    /* ---------- helper: "yyyy/MM/dd HH:mm" -> minutes from 00:00 of that day ------ */
    private func toMinutes(t: String): Int64 {
        let dt = DateTime.parse(t, "yyyy/MM/dd HH:mm")
        dt.hour * 60 + dt.minute
    }

    /* -------------- 1. add if not yet present ------------------------ */
    public func add_course(course: Course): Unit {
        for (c in this.courses) {
            if (c == course) { return }  // already here
        }
        this.courses.add(course)
    }

    /* -------------- 2. remove if present ----------------------------- */
    public func remove_course(course: Course): Unit {
        for (i in 0..this.courses.size) {
            if (this.courses[i] == course) {
                this.courses.remove(at: i)
                return
            }
        }
    }

    /* -------------- 3. is the room free at a single minute ---------- */
    public func is_free_at(check_time: String): Bool {
        let m = this.toMinutes(check_time)
        for (c in this.courses) {
            let startM = this.toMinutes(c.start_time)
            let endM   = this.toMinutes(c.end_time)
            if (m >= startM && m < endM) {  // [start, end)
                return false
            }
        }
        return true
    }

    /* -------------- 4. would this new course overlap any existing one? */
    public func check_course_conflict(new_course: Course): Bool {
        let ns = this.toMinutes(new_course.start_time)
        let ne = this.toMinutes(new_course.end_time)

        for (c in this.courses) {
            let s = this.toMinutes(c.start_time)
            let e = this.toMinutes(c.end_time)
            /* overlap when NOT (ne <= s OR ns >= e) */
            if (!(ne <= s || ns >= e)) {
                return false  // conflict found
            }
        }
        return true  // no conflict
    }
}

