class ClassRegistrationSystem {
    var students: ArrayList<HashMap<String, String>>
    var students_registration_classes: HashMap<String, ArrayList<String>>

    public init() {
        this.students = ArrayList<HashMap<String, String>>()
        this.students_registration_classes = HashMap<String, ArrayList<String>>()
    }

    public func register_student(student: HashMap<String, String>): Int64 {
        let name = student["name"] ?? ""
        for (s in this.students) {
            if (s["name"] ?? "" == name) {
                return 0
            }
        }
        this.students.add(student)
        return 1
    }

    public func register_class(student_name: String, class_name: String): ArrayList<String> {
        if (!this.students_registration_classes.contains(student_name)) {
            this.students_registration_classes[student_name] = ArrayList<String>()
        }
        let classes = this.students_registration_classes[student_name] ?? ArrayList<String>()
        if (!classes.contains(class_name)) {
            classes.add(class_name)
        }
        return classes
    }

    public func get_students_by_major(major: String): ArrayList<String> {
        let res = ArrayList<String>()
        for (s in this.students) {
            if (s["major"] ?? "" == major) {
                res.add(s["name"] ?? "")
            }
        }
        return res
    }

    public func get_all_major(): ArrayList<String> {
        let set = HashSet<String>()
        for (s in this.students) {
            set.add(s["major"] ?? "")
        }
        return ArrayList<String>(set)
    }

    public func get_most_popular_class_in_major(major: String): String {
        let majorStudents = this.get_students_by_major(major)
        let classCount = HashMap<String, Int64>()
        for (name in majorStudents) {
            let classes = this.students_registration_classes[name] ?? ArrayList<String>()
            for (cls in classes) {
                classCount[cls] = (classCount[cls] ?? 0) + 1
            }
        }
        var maxCls = ""
        var maxCnt = 0
        for ((cls, cnt) in classCount) {
            if (cnt > maxCnt) {
                maxCnt = cnt
                maxCls = cls
            }
        }
        return maxCls
    }
}

import std.collection.ArrayList
import std.math.*

class CombinationCalculator {

    let datas: ArrayList<String>

    public init(datas: ArrayList<String>) {
        this.datas = datas
    }

    public static func factorial(n: Int64): Int64 {
        var result = 1
        for (i in 1..n + 1) {
            result *= i
        }
        return result
    }

    public static func count(n: Int64, m: Int64): Int64 {
        if (m < 0 || m > n) { return 0 }
        if (m == 0 || m == n) { return 1 }
        var num = 1
        var den = 1
        let k = min(m, n - m)
        for (i in 1..k + 1) {
            num *= n - k + i
            den *= i
        }
        return num / den
    }

    public static func count_all(n: Int64): Int64 {
        if (n < 0) { return 0 }
        if (n >= 63) { return Int64.Max }
        return (1 << n) - 1
    }

    public func select(m: Int64): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        let temp   = ArrayList<String>()
        _select(0, temp, m, result)
        return result
    }

    public func select_all(): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        for (k in 1..datas.size + 1) {
            let part = select(k)
            for (comb in part) {
                result.add(comb)
            }
        }
        return result
    }

    public func _select(start: Int64, cur: ArrayList<String>, left: Int64,
                        result: ArrayList<ArrayList<String>>): Unit {
        if (left == 0) {
            result.add(ArrayList<String>(cur))
            return
        }
        for (i in start..datas.size - left + 1) {
            cur.add(datas[i])
            _select(i + 1, cur, left - 1, result)
            cur.remove(at: cur.size - 1)
        }
    }
}

import std.math.abs
import std.collection.*

class ComplexNumber <: Equatable<ComplexNumber> {
    public var real: Float64
    public var imaginary: Float64

    public init(real: Float64, imaginary: Float64) {
        this.real = real
        this.imaginary = imaginary
    }

    public override operator func != (that: ComplexNumber): Bool {
        return this.real != that.real || this.imaginary != that.imaginary
    }

    public override operator func == (that: ComplexNumber): Bool {
        return this.real == that.real && this.imaginary == that.imaginary
    }
}

class ComplexCalculator {
    public init() {}

    public static func add(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        return ComplexNumber(c1.real + c2.real, c1.imaginary + c2.imaginary)
    }

    public static func subtract(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        return ComplexNumber(c1.real - c2.real, c1.imaginary - c2.imaginary)
    }

    public static func multiply(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        let real = c1.real * c2.real - c1.imaginary * c2.imaginary
        let imag = c1.real * c2.imaginary + c1.imaginary * c2.real
        return ComplexNumber(real, imag)
    }

    public static func divide(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        let denom = c2.real * c2.real + c2.imaginary * c2.imaginary
        let real = (c1.real * c2.real + c1.imaginary * c2.imaginary) / denom
        let imag = (c1.imaginary * c2.real - c1.real * c2.imaginary) / denom
        return ComplexNumber(real, imag)
    }
}

import std.collection.ArrayList
import std.fs.*
import std.io.*
import std.unicode.*

class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let content = readText(file_name)
        let lines = content.split("\n")
        let title = ArrayList<String>()
        let data = ArrayList<ArrayList<String>>()
        for (i in 0..lines.size) {
            let line = lines[i].trim()
            if (line == "") { continue }
            let parts = line.split(",").map({s => s.trim()})
            if (i == 0) {
                for (p in parts) { title.add(p) }
            } else {
                let row = ArrayList<String>()
                for (p in parts) { row.add(p) }
                data.add(row)
            }
        }
        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        try {
            let writer = FileWriter(file_name)
            for (row in data) {
                let line = row.join(",")
                writer.write(line)
                writer.write("\n")
            }
            writer.close()
            return 1
        } catch (_) {
            return 0
        }
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, oldData) = read_csv(save_file_name)
        let newData = ArrayList<ArrayList<String>>()
        newData.add(title)
        for (row in oldData) {
            let newRow = ArrayList<String>()
            if (N < row.size) {
                let cell = row[N]
                let upper = cell.upper()
                newRow.add(upper)
            }
            newData.add(newRow)
        }
        let outName = "${save_file_name.subString(0, save_file_name.lastIndexOf("."))}_process.csv"
        return write_csv(newData, outName)
    }
}

