import std.collection.*
import std.math.*

class DataStatistics {

    public func mean(data: ArrayList<Int64>): Float64 {
        if (data.size == 0) {
            return 0.0
        }
        var sum: Float64 = 0.0
        for (x in data) {
            sum += Float64(x)
        }
        let avg = sum / Float64(data.size)
        return round(avg * 100.0) / 100.0
    }

    public func median(data: ArrayList<Int64>): Float64 {
        if (data.size == 0) {
            return 0.0
        }
        let sorted = ArrayList<Int64>(data)
        sort(sorted)
        let n = sorted.size
        if (n % 2 == 1) {
            return round(Float64(sorted[n / 2]) * 100.0) / 100.0
        } else {
            let mid = (Float64(sorted[n / 2 - 1]) + Float64(sorted[n / 2])) / 2.0
            return round(mid * 100.0) / 100.0
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let freq = HashMap<Int64, Int64>()
        for (x in data) {
            freq[x] = (freq.get(x) ?? 0) + 1
        }
        var maxCount: Int64 = 0
        for (pair in freq) {
            if (pair.1 > maxCount) {
                maxCount = pair.1
            }
        }
        let modes = ArrayList<Int64>()
        for (pair in freq) {
            if (pair.1 == maxCount) {
                modes.add(pair.0)
            }
        }
        sort(modes)
        return modes
    }
}

import std.collection.ArrayList
