class DataStatistics2 {
    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        this.data = data
    }

    public func get_sum(): Float64 {
        var sum = 0.0
        for (x in this.data) {
            sum += x
        }
        return sum
    }

    public func get_min(): Float64 {
        if (this.data.size == 0) {
            return 0.0
        }
        var min = this.data[0]
        for (x in this.data) {
            if (x < min) {
                min = x
            }
        }
        return min
    }

    public func get_max(): Float64 {
        if (this.data.size == 0) {
            return 0.0
        }
        var max = this.data[0]
        for (x in this.data) {
            if (x > max) {
                max = x
            }
        }
        return max
    }

    public func get_variance(): Float64 {
        let n = this.data.size
        if (n <= 1) {
            return 0.0
        }
        let mean = this.get_sum() / Float64(n)
        var sum_sq = 0.0
        for (x in this.data) {
            let diff = x - mean
            sum_sq += diff * diff
        }
        let variance = sum_sq / Float64(n - 1)
        return round(variance * 100.0) / 100.0
    }

    public func get_std_deviation(): Float64 {
        let variance = this.get_variance()
        let std = sqrt(variance)
        return round(std * 100.0) / 100.0
    }

    public func get_correlation(): Float64 {
        // Single dataset autocorrelation: return 1.0 as placeholder
        return 1.0
    }
}

import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.abs
import std.math.pow

class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size
        if (n != data2.size || n == 0) {
            return 0.0
        }
        var sum1 = 0.0, sum2 = 0.0, sum12 = 0.0, sum1sq = 0.0, sum2sq = 0.0
        for (i in 0..n) {
            let x = data1[i]
            let y = data2[i]
            sum1 += x
            sum2 += y
            sum12 += x * y
            sum1sq += x * x
            sum2sq += y * y
        }
        let numerator = n * sum12 - sum1 * sum2
        let denom = sqrt((n * sum1sq - sum1 * sum1) * (n * sum2sq - sum2 * sum2))
        if (denom == 0.0) {
            return 0.0
        }
        return numerator / denom
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size
        if (n < 3) {
            return 0.0
        }
        var sum = 0.0
        for (x in data) {
            sum += x
        }
        let mean = sum / (n.toFloat64())
        var varianceAcc = 0.0
        for (x in data) {
            let d = x - mean
            varianceAcc += d * d
        }
        let std_dev = sqrt(varianceAcc / n.toFloat64())
        if (std_dev == 0.0) {
            return 0.0
        }
        var skewAcc = 0.0
        for (x in data) {
            let d = (x - mean) / std_dev
            skewAcc += d * d * d
        }
        return skewAcc * n.toFloat64() / ((n - 1).toFloat64() * (n - 2).toFloat64())
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size
        if (n < 4) {
            return 0.0
        }
        var sum = 0.0
        for (x in data) {
            sum += x
        }
        let mean = sum / (n.toFloat64())
        var varianceAcc = 0.0
        for (x in data) {
            let d = x - mean
            varianceAcc += d * d
        }
        let std_dev = sqrt(varianceAcc / n.toFloat64())
        if (std_dev == 0.0) {
            return 0.0
        }
        var kurtAcc = 0.0
        for (x in data) {
            let d = (x - mean) / std_dev
            kurtAcc += d * d * d * d
        }
        let term = (n.toFloat64() * (n + 1.0)) / ((n - 1).toFloat64() * (n - 2).toFloat64() * (n - 3).toFloat64())
        let correction = 3.0 * ((n - 1).toFloat64() * (n - 1).toFloat64()) / ((n - 2).toFloat64() * (n - 3).toFloat64())
        return term * kurtAcc - correction
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let n = data.size
        let result = ArrayList<Float64>()
        let coeff = 1.0 / (sigma * sqrt(2.0 * 3.141592653589793))
        for (x in data) {
            let exponent = -0.5 * pow((x - mu) / sigma, 2.0)
            result.add(coeff * exp(exponent))
        }
        return result
    }
}

import std.collection.ArrayList

class DecryptionUtils {

    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        let out = ArrayList<Rune>()
        for (ch in ciphertext.runes()) {
            if ('a' <= ch && ch <= 'z') {
                let base = Int64('a')
                let delta = (Int64(ch) - base - shift + 26) % 26
                out.add(Rune(base + delta))
            } else if ('A' <= ch && ch <= 'Z') {
                let base = Int64('A')
                let delta = (Int64(ch) - base - shift + 26) % 26
                out.add(Rune(base + delta))
            } else {
                out.add(ch)
            }
        }
        String.fromRunes(out)
    }

    public func vigenere_decipher(ciphertext: String): String {
        let keyRunes = key.toRuneArray()
        let keyLen = keyRunes.size
        let out = ArrayList<Rune>()
        var ki = 0
        for (ch in ciphertext.runes()) {
            if ('a' <= ch && ch <= 'z') {
                let base = Int64('a')
                let k = Int64(keyRunes[ki % keyLen]) - base
                let delta = (Int64(ch) - base - k + 26) % 26
                out.add(Rune(base + delta))
                ki++
            } else if ('A' <= ch && ch <= 'Z') {
                let base = Int64('A')
                let k = Int64(keyRunes[ki % keyLen] | 32) - Int64('a')
                let delta = (Int64(ch) - base - k + 26) % 26
                out.add(Rune(base + delta))
                ki++
            } else {
                out.add(ch)
            }
        }
        String.fromRunes(out)
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        let txt = encrypted_text.toRuneArray()
        let n = txt.size
        var cycle = 2 * rails - 2
        if (cycle == 0) {
            cycle = 1
        }
        var idx = 0
        let out = Array<Rune>(n, r' ')
        for (r in 0..rails) {
            var i = r
            while (i < n) {
                out[i] = txt[idx]
                idx++
                if (r == 0 || r == rails - 1) {
                    i += cycle
                } else {
                    let next = i + cycle - 2 * r
                    if (next < n) {
                        out[next] = txt[idx]
                        idx++
                    }
                    i += cycle
                }
            }
        }
        String.fromRunes(out)
    }
}

