import std.collection.*
import std.sort.*

class EightPuzzle {

    let initial_state: ArrayList<ArrayList<Int64>>
    let goal_state: ArrayList<ArrayList<Int64>>

    public init(initial_state: ArrayList<ArrayList<Int64>>) {
        this.initial_state = initial_state
        this.goal_state = ArrayList<ArrayList<Int64>>([
            ArrayList<Int64>([1, 2, 3]),
            ArrayList<Int64>([4, 5, 6]),
            ArrayList<Int64>([7, 8, 0])
        ])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        for (i in 0..3) {
            for (j in 0..3) {
                if (state[i][j] == 0) {
                    return (i, j)
                }
            }
        }
        return (-1, -1)
    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        let (i, j) = find_blank(state)
        var new_state = ArrayList<ArrayList<Int64>>()
        for (row in state) {
            new_state.add(ArrayList<Int64>(row))
        }
        var ni = i
        var nj = j
        if (direction == "up") {
            ni = i - 1
        } else if (direction == "down") {
            ni = i + 1
        } else if (direction == "left") {
            nj = j - 1
        } else if (direction == "right") {
            nj = j + 1
        }
        if (ni >= 0 && ni < 3 && nj >= 0 && nj < 3) {
            let temp = new_state[i][j]
            new_state[i][j] = new_state[ni][nj]
            new_state[ni][nj] = temp
        }
        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        let (i, j) = find_blank(state)
        var moves = ArrayList<String>()
        if (i > 0) { moves.add("up") }
        if (i < 2) { moves.add("down") }
        if (j > 0) { moves.add("left") }
        if (j < 2) { moves.add("right") }
        return moves
    }

    public func solve(): ArrayList<String> {
        var open_list = ArrayList<(ArrayList<ArrayList<Int64>>, ArrayList<String>)>()
        var visited = HashSet<String>()
        open_list.add((initial_state, ArrayList<String>()))
        while (open_list.size > 0) {
            let (current, path) = open_list.remove(at: 0)
            let key = state_to_string(current)
            if (visited.contains(key)) {
                continue
            }
            visited.add(key)
            if (is_goal(current)) {
                return path
            }
            let moves = get_possible_moves(current)
            for (move_dir in moves) {
                let next_state = move(current, move_dir)
                var new_path = ArrayList<String>(path)
                new_path.add(move_dir)
                open_list.add((next_state, new_path))
            }
        }
        return ArrayList<String>()
    }

    private func state_to_string(state: ArrayList<ArrayList<Int64>>): String {
        var s = ""
        for (row in state) {
            for (val in row) {
                s = "${s}${val},"
            }
        }
        return s
    }

    private func is_goal(state: ArrayList<ArrayList<Int64>>): Bool {
        for (i in 0..3) {
            for (j in 0..3) {
                if (state[i][j] != goal_state[i][j]) {
                    return false
                }
            }
        }
        return true
    }
}

import std.time.DateTime
import std.collection.ArrayList
import std.collection.HashMap

class EmailClient {

    let addr: String
    let capacity: Int64
    var inbox: ArrayList<HashMap<String, Any>>

    public init(addr: String, capacity: Int64) {
        this.addr = addr
        this.capacity = capacity
        this.inbox = ArrayList<HashMap<String, Any>>()
    }

    public func send_to(recv: EmailClient, content: String, size: Int64): Bool {
        if (recv.is_full_with_one_more_email(size)) {
            return false
        }
        let now = DateTime.now()
        let mail = HashMap<String, Any>([
            ("sender", this.addr),
            ("receiver", recv.addr),
            ("content", content),
            ("size", size),
            ("time", "${now}"),
            ("state", "unread")
        ])
        recv.inbox.add(mail)
        return true
    }

    public func fetch(): HashMap<String, Any> {
        for (i in 0..inbox.size) {
            let mail = inbox[i]
            if (mail["state"] == "unread") {
                mail["state"] = "read"
                return mail
            }
        }
        return HashMap<String, Any>()
    }

    public func is_full_with_one_more_email(size: Int64): Bool {
        (get_occupied_size() + size) > capacity
    }

    public func get_occupied_size(): Int64 {
        var total = 0
        for (mail in inbox) {
            total += mail["size"] as Int64
        }
        total
    }

    public func clear_inbox(size: Int64): Unit {
        var needed = size
        while (needed > 0 && inbox.size > 0) {
            let oldest = inbox.remove(at: 0)
            needed -= oldest["size"] as Int64
        }
    }
}

import std.collection.ArrayList

class EncryptionUtils {

    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        let runes = plaintext.toRuneArray()
        let n = runes.size
        var out = ArrayList<Rune>([])
        for (i in 0..n) {
            let r = runes[i]
            let base: Rune = if (r >= r'a' && r <= r'z') { r'a' }
                             else if (r >= r'A' && r <= r'Z') { r'A' }
                             else { r } // non-alphabet unchanged
            if (r >= r'a' && r <= r'z' || r >= r'A' && r <= r'Z') {
                let off = ((r - base + shift) % 26 + 26) % 26
                out.add(base + off)
            } else {
                out.add(r)
            }
        }
        String.fromRuneArray(out)
    }

    public func vigenere_cipher(plain_text: String): String {
        let pr = plain_text.toRuneArray()
        let kr = key.toRuneArray()
        let pn = pr.size
        let kn = kr.size
        var out = ArrayList<Rune>([])
        for (i in 0..pn) {
            let p = pr[i]
            let k = kr[i % kn]
            let base: Rune = if (p >= r'a' && p <= r'z') { r'a' }
                             else if (p >= r'A' && p <= r'A') { r'A' }
                             else { p }
            if (p >= r'a' && p <= r'z' || p >= r'A' && p <= r'Z') {
                let off = ((p - base + (k - base)) % 26 + 26) % 26
                out.add(base + off)
            } else {
                out.add(p)
            }
        }
        String.fromRuneArray(out)
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        let pr = plain_text.toRuneArray()
        let n = pr.size
        if (rails <= 1 || n == 0) {
            return plain_text
        }
        var fence = ArrayList<ArrayList<Rune>>([])
        for (i in 0..rails) {
            fence.add(ArrayList<Rune>([]))
        }
        var rail = 0
        var down = true
        for (i in 0..n) {
            fence[rail].add(pr[i])
            if (rail == 0) {
                down = true
            } else if (rail == rails - 1) {
                down = false
            }
            rail = if (down) { rail + 1 } else { rail - 1 }
        }
        var out = ArrayList<Rune>([])
        for (r in fence) {
            for (c in r) {
                out.add(c)
            }
        }
        String.fromRuneArray(out)
    }
}

import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        let tokens = transform(expression).split("").filter({s => !s.isEmpty})
        var stack = ArrayList<Decimal>()
        for (tok in tokens) {
            if (!is_operator(tok)) {
                stack.add(Decimal(tok))
                continue
            }
            let b = stack.remove(at: stack.size - 1)
            let a = stack.remove(at: stack.size - 1)
            stack.add(_calculate(a, b, tok))
        }
        return Float64(stack[0])
    }

    public func prepare(expression: String): Unit {
        postfix_stack.clear()
        let tokens = transform(expression).split("").filter({s => !s.isEmpty})
        var op_stack = ArrayList<String>()
        for (tok in tokens) {
            if (!is_operator(tok)) {
                postfix_stack.add(tok)
                continue
            }
            if (tok == "(") {
                op_stack.add(tok)
                continue
            }
            if (tok == ")") {
                while (op_stack.size > 0 && op_stack[op_stack.size - 1] != "(") {
                    postfix_stack.add(op_stack.remove(at: op_stack.size - 1))
                }
                if (op_stack.size > 0) {
                    op_stack.remove(at: op_stack.size - 1)
                }
                continue
            }
            while (op_stack.size > 0 && compare(tok, op_stack[op_stack.size - 1])) {
                postfix_stack.add(op_stack.remove(at: op_stack.size - 1))
            }
            op_stack.add(tok)
        }
        while (op_stack.size > 0) {
            postfix_stack.add(op_stack.remove(at: op_stack.size - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        let ops = ["+", "-", "*", "/", "(", ")", "%"]
        return ops.contains(c)
    }

    public func compare(cur: String, peek: String): Bool {
        let ops = ["+", "-", "*", "/", "(", ")", "%", "#"]
        let cur_idx = ops.indexOf(cur) ?? 7
        let peek_idx = ops.indexOf(peek) ?? 7
        let cur_pri = operat_priority[cur_idx]
        let peek_pri = operat_priority[peek_idx]
        return cur_pri <= peek_pri && peek != "("
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => first_value + second_value
            case "-" => first_value - second_value
            case "*" => first_value * second_value
            case "/" => first_value / second_value
            case "%" => first_value % second_value
            case _   => Decimal("0")
        }
    }

    public static func transform(expression: String): String {
        return expression.replace(" ", "")
    }
}

