        return true
    }

    public func check_winner(): Option<String> {
        let directions: ArrayList<(Int64, Int64)> = ArrayList([
            (0, 1),  // horizontal
            (1, 0),  // vertical
            (1, 1),  // diagonal down-right
            (1, -1)  // diagonal down-left
        ])
        for (row in 0..board_size) {
            for (col in 0..board_size) {
                let symbol = board[row][col]
                if (symbol == " ") {
                    continue
                }
                for (dir in directions) {
                    if (_check_five_in_a_row(row, col, dir)) {
                        return Some<String>(symbol)
                    }
                }
            }
        }
        return None<String>
    }

    public func _check_five_in_a_row(row: Int64, col: Int64, direction: (Int64, Int64)): Bool {
        let (dx, dy) = direction
        let symbol = board[row][col]
        var count = 1
        // forward direction
        var r = row + dx
        var c = col + dy
        while (r >= 0 && r < board_size && c >= 0 && c < board_size && board[r][c] == symbol) {
            count += 1
            r += dx
            c += dy
        }
        // backward direction
        r = row - dx
        c = col - dy
        while (r >= 0 && r < board_size && c >= 0 && c < board_size && board[r][c] == symbol) {
            count += 1
            r -= dx
            c -= dy
        }
        return count >= 5
    }
}

import std.collection.*

class Hotel {

    let name: String
    let available_rooms: HashMap<String, Int64>
    var booked_rooms: HashMap<String, HashMap<String, Int64>>

    public init(name: String, rooms: HashMap<String, Int64>) {
        this.name = name
        this.available_rooms = HashMap<String, Int64>(rooms)
        this.booked_rooms = HashMap<String, HashMap<String, Int64>>()
    }

    public func book_room(room_type: String, room_number: Int64, name: String): String {
        let remaining = this.available_rooms.getOrDefault(room_type, 0)
        if (room_number <= remaining) {
            this.available_rooms[room_type] = remaining - room_number
            let guestBooked = this.booked_rooms.getOrDefault(room_type, HashMap<String, Int64>())
            guestBooked[name] = guestBooked.getOrDefault(name, 0) + room_number
            this.booked_rooms[room_type] = guestBooked
            return "Success!"
        } else if (remaining > 0) {
            return remaining.toString()
        } else {
            return "false"
        }
    }

    public func check_in(room_type: String, room_number: Int64, name: String): Bool {
        let guestBooked = this.booked_rooms.getOrDefault(room_type, HashMap<String, Int64>())
        let bookedQty = guestBooked.getOrDefault(name, 0)
        if (room_number > bookedQty) {
            return false
        }
        let newQty = bookedQty - room_number
        if (newQty == 0) {
            guestBooked.remove(name)
        } else {
            guestBooked[name] = newQty
        }
        this.booked_rooms[room_type] = guestBooked
        return true
    }

    public func check_out(room_type: String, room_number: Int64): Unit {
        let current = this.available_rooms.getOrDefault(room_type, 0)
        this.available_rooms[room_type] = current + room_number
    }

    public func get_available_rooms(room_type: String): Int64 {
        this.available_rooms.getOrDefault(room_type, 0)
    }
}

