import std.collection.ArrayList

class Interpolation {

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let res = ArrayList<Float64>()
        for (xi in x_interp) {
            if (xi <= x[0]) {
                res.add(y[0])
                continue
            }
            if (xi >= x[x.size - 1]) {
                res.add(y[y.size - 1])
                continue
            }
            var i = 0
            while (i < x.size - 1 && x[i + 1] < xi) {
                i++
            }
            let t = (xi - x[i]) / (x[i + 1] - x[i])
            res.add(y[i] + t * (y[i + 1] - y[i]))
        }
        return res
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let res = ArrayList<Float64>()
        for (k in 0..x_interp.size) {
            let xi = x_interp[k]
            let yi = y_interp[k]

            var ix = 0
            while (ix < x.size - 1 && x[ix + 1] < xi) { ix++ }
            var iy = 0
            while (iy < y.size - 1 && y[iy + 1] < yi) { iy++ }

            let tx = (xi - x[ix]) / (x[ix + 1] - x[ix])
            let ty = (yi - y[iy]) / (y[iy + 1] - y[iy])

            let z00 = z[iy][ix]
            let z01 = z[iy][ix + 1]
            let z10 = z[iy + 1][ix]
            let z11 = z[iy + 1][ix + 1]

            let z0 = z00 + tx * (z01 - z00)
            let z1 = z10 + tx * (z11 - z10)
            let zi = z0 + ty * (z1 - z0)

            res.add(zi)
        }
        return res
    }
}

