class IPAddress {

    let ip_address: String

    public init(ip_address: String) {
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        let parts = this.ip_address.split(".")
        if (parts.size != 4) {
            return false
        }
        for (part in parts) {
            match (Int64.parse(part)) {
                case Some(n) =>
                    if (n < 0 || n > 255) {
                        return false
                    }
                case None => return false
            }
        }
        true
    }

    public func get_octets(): ArrayList<String> {
        if (!this.is_valid()) {
            return ArrayList<String>([])
        }
        ArrayList<String>(this.ip_address.split("."))
    }

    public func get_binary(): String {
        if (!this.is_valid()) {
            return ""
        }
        let parts = this.ip_address.split(".")
        let out = StringBuffer()
        for (i in 0..4) {
            let n = Int64.parse(parts[i]).getOrThrow()
            out.append(String.format(n, "08b"))
            if (i < 3) {
                out.append(".")
            }
        }
        out.toString()
    }
}

