class JobMarketplace {
    let jobListings: ArrayList<JobListing>
    let resumes: ArrayList<Resume>

    public init() {
        this.jobListings = ArrayList<JobListing>()
        this.resumes = ArrayList<Resume>()
    }

    public func post_job(job_title: String, company: String, requirements: ArrayList<String>): Unit {
        jobListings.add(JobListing(job_title, company, requirements))
    }

    public func remove_job(job: JobListing): Unit {
        for (i in 0..jobListings.size) {
            if (jobListings[i] == job) {
                jobListings.remove(at: i)
                break
            }
        }
    }

    public func submit_resume(name: String, skills: ArrayList<String>, experience: String): Unit {
        resumes.add(Resume(name, skills, experience))
    }

    public func withdraw_resume(resume: Resume): Unit {
        for (i in 0..resumes.size) {
            if (resumes[i] == resume) {
                resumes.remove(at: i)
                break
            }
        }
    }

    public func search_jobs(criteria: String): ArrayList<JobListing> {
        let result = ArrayList<JobListing>()
        for (job in jobListings) {
            for (req in job.requirements) {
                if (req == criteria) {
                    result.add(job)
                    break
                }
            }
        }
        return result
    }

    public func get_job_applicants(job: JobListing): ArrayList<Resume> {
        let result = ArrayList<Resume>()
        for (resume in resumes) {
            if (JobMarketplace.matches_requirements(resume, job.requirements)) {
                result.add(resume)
            }
        }
        return result
    }

    public static func matches_requirements(resume: Resume, requirements: ArrayList<String>): Bool {
        for (req in requirements) {
            var found = false
            for (skill in resume.skills) {
                if (skill == req) {
                    found = true
                    break
                }
            }
            if (!found) {
                return false
            }
        }
        return true
    }
}

import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var po = 0.0
        var pe = 0.0
        var rowSum = Array<Float64>([0.0, 0.0, 0.0])
        var colSum = Array<Float64>([0.0, 0.0, 0.0])
        var total: Float64 = 0.0

        for (i in 0..k) {
            var row: Float64 = 0.0
            for (j in 0..k) {
                let v = testData[i][j].toFloat64()
                row += v
                colSum[j] += v
                total += v
            }
            rowSum[i] = row
        }

        for (i in 0..k) {
            po += testData[i][i].toFloat64()
            pe += rowSum[i] * colSum[i]
        }
        po = po / total
        pe = pe / (total * total)

        return (po - pe) / (1.0 - pe)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var p = Array<Float64>(Array<Float64>(k, { _ => 0.0 }))
        var P = Array<Float64>(Array<Float64>(N, { _ => 0.0 }))
        var Pbar = 0.0
        var Pe = 0.0

        for (j in 0..k) {
            var sum: Float64 = 0.0
            for (i in 0..N) {
                sum += testData[i][j].toFloat64()
            }
            p[j] = sum / (N.toFloat64() * n.toFloat64())
        }

        for (i in 0..N) {
            var sumSquares: Float64 = 0.0
            for (j in 0..k) {
                let x = testData[i][j].toFloat64()
                sumSquares += x * x
            }
            P[i] = (sumSquares - n.toFloat64()) / (n.toFloat64() * (n.toFloat64() - 1.0))
        }

        for (i in 0..N) {
            Pbar += P[i]
        }
        Pbar = Pbar / N.toFloat64()

        for (j in 0..k) {
            Pe += p[j] * p[j]
        }

        return (Pbar - Pe) / (1.0 - Pe)
    }
}

import std.collection.ArrayList
