class LongestWord {

    let word_list: ArrayList<String>

    public init() {
        this.word_list = ArrayList<String>()
    }

    public func add_word(word: String): Unit {
        this.word_list.add(word)
    }

    public func find_longest_word(sentence: String): String {
        if (this.word_list.size == 0) {
            return ""
        }

        // Remove punctuation by keeping only letters (strictly case-sensitive)
        let re = Regex("[A-Za-z]+")
        let matches = re.findAll(sentence)
        var longest = ""
        for (m in matches) {
            let w = m.group(0)
            if (this.word_list.contains(w) && w.size > longest.size) {
                longest = w
            }
        }
        return longest
    }
}

import std.collection.ArrayList
import std.collection.HashSet
import std.random.Random

class MahjongConnect {

    let BOARD_SIZE: ArrayList<Int64>
    let ICONS: ArrayList<String>
    var board: ArrayList<ArrayList<String>>

    public init(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>) {
        this.BOARD_SIZE = BOARD_SIZE
        this.ICONS = ICONS
        this.board = create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]
        let iconCount = ICONS.size
        let totalCells = rows * cols

        // Ensure even number of each icon
        let rng = Random()
        var tiles = ArrayList<String>()
        for (i in 0..totalCells) {
            tiles.add(ICONS[i % iconCount])
        }

        // Shuffle tiles
        for (i in 0..totalCells) {
            let j = rng.nextInt64() % totalCells
            if (i != j) {
                let tmp = tiles[i]
                tiles[i] = tiles[j]
                tiles[j] = tmp
            }
        }

        let board = ArrayList<ArrayList<String>>()
        var idx = 0
        for (i in 0..rows) {
            let row = ArrayList<String>()
            for (j in 0..cols) {
                row.add(tiles[idx])
                idx += 1
            }
            board.add(row)
        }
        return board
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]

        // Check bounds
        if (x1 < 0 || x1 >= rows || y1 < 0 || y1 >= cols) { return false }
        if (x2 < 0 || x2 >= rows || y2 < 0 || y2 >= cols) { return false }

        // Same position
        if (x1 == x2 && y1 == y2) { return false }

        // Same icon
        if (board[x1][y1] != board[x2][y2]) { return false }

        // Path exists
        return has_path(pos1, pos2)
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]

        // BFS with at most 2 bends
        let dirs = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        var queue = ArrayList<((Int64, Int64), Int64, Int64)>() // (pos, direction, bends)
        var visited = HashSet<(Int64, Int64, Int64)>() // (x, y, dir)

        func inBounds(x: Int64, y: Int64): Bool {
            return x >= 0 && x < rows && y >= 0 && y < cols
        }

        // Start from pos1 in all 4 directions
        for (d in 0..4) {
            let (dx, dy) = dirs[d]
            let nx = x1 + dx
            let ny = y1 + dy
            if (inBounds(nx, ny) && board[nx][ny] == " ") {
                queue.add(((nx, ny), d, 0))
                visited.add((nx, ny, d))
            } else if (nx == x2 && ny == y2) {
                return true
            }
        }

        while (queue.size > 0) {
            let ((cx, cy), dir, bends) = queue.remove(at: 0)
            if (cx == x2 && cy == y2) { return true }

            // Continue straight
            let (dx, dy) = dirs[dir]
            let nx = cx + dx
            let ny = cy + dy
            if (inBounds(nx, ny) && board[nx][ny] == " " && !visited.contains((nx, ny, dir))) {
                visited.add((nx, ny, dir))
                queue.add(((nx, ny), dir, bends))
            } else if (nx == x2 && ny == y2) {
                return true
            }

            // Try turns (bend <= 2)
            if (bends < 2) {
                for (nd in 0..4) {
                    if (nd == dir) { continue }
                    let (ndx, ndy) = dirs[nd]
                    let nnx = cx + ndx
                    let nny = cy + ndy
                    if (inBounds(nnx, nny) && board[nnx][nny] == " " && !visited.contains((nnx, nny, nd))) {
                        visited.add((nnx, nny, nd))
                        queue.add(((nnx, nny), nd, bends + 1))
                    } else if (nnx == x2 && nny == y2) {
                        return true
                    }
                }
            }
        }
        return false
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        for (v in visited) {
            if (v == pos) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        board[x1][y1] = " "
        board[x2][y2] = " "
    }

    public func is_game_over(): Bool {
        for (row in board) {
            for (cell in row) {
                if (cell != " ") {
                    return false
                }
            }
        }
        return true
    }
}

import std.collection.*
import std.sort.*

class Manacher {
    let input_string: String

    public init(input_string: String) {
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        let left  = center - diff
        let right = center + diff
        if (left < 0 || right >= string.size) {
            return diff - 1
        }
        if (string[left] == string[right]) {
            return palindromic_length(center, diff + 1, string)
        } else {
            return diff - 1
        }
    }

    public func palindromic_string(): String {
        // Build transformed string: insert '|' between every character and at ends
        let transformed = ArrayList<Rune>()
        transformed.append(r'|')
        for (ch in input_string.runes()) {
            transformed.append(ch)
            transformed.append(r'|')
        }
        let s = String(transformed.toArray())

        var maxLen: Int64 = 0
        var bestCenter: Int64 = 0

        for (i in 0..s.size) {
            let len = palindromic_length(i, 1, s)
            if (len > maxLen) {
                maxLen = len
                bestCenter = i
            }
        }

        let start = bestCenter - maxLen
        let end   = bestCenter + maxLen
        let resultRunes = ArrayList<Rune>()
        for (i in start..(end + 1)) {
            if (s[i] != r'|') {
                resultRunes.append(s[i])
            }
        }
        return String(resultRunes.toArray())
    }
}

import std.collection.ArrayList
// abs available automatically in Cangjie runtime

class MetricsCalculator {
    var true_positives: Int64
    var false_positives: Int64
    var false_negatives: Int64
    var true_negatives: Int64

    public init() {
        this.true_positives = 0
        this.false_positives = 0
        this.false_negatives = 0
        this.true_negatives = 0
    }

    /* helper: compare and update counts in one loop */
    func _count(pred: ArrayList<Int64>, true_lbl: ArrayList<Int64>): Unit {
        let n = pred.size
        for (i in 0..n) {
            let p = pred[i]
            let t = true_lbl[i]
            match ((p, t)) {
                case (1, 1) => this.true_positives += 1
                case (1, 0) => this.false_positives += 1
                case (0, 1) => this.false_negatives += 1
                case _      => this.true_negatives += 1
            }
        }
    }

    /* update internal counters according to new batch */
    public func update(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Unit {
        if (predicted_labels.size != true_labels.size) { return }
        this._count(predicted_labels, true_labels)
    }

    public func precision(_p: ArrayList<Int64>, _t: ArrayList<Int64>): Float64 {
        let t_pos = this.true_positives
        let f_pos = this.false_positives
        let denom = t_pos + f_pos
        if (denom == 0L) { return 0.0 }
        Float64(t_pos) / Float64(denom)
    }

    public func recall(_p: ArrayList<Int64>, _t: ArrayList<Int64>): Float64 {
        let t_pos = this.true_positives
        let f_neg = this.false_negatives
        let denom = t_pos + f_neg
        if (denom == 0L) { return 0.0 }
        Float64(t_pos) / Float64(denom)
    }

    public func f1_score(_p: ArrayList<Int64>, _t: ArrayList<Int64>): Float64 {
        let p_val = this.precision(_p, _t)
        let r_val = this.recall(_p, _t)
        let sum = p_val + r_val
        if (sum == 0.0) { return 0.0 }
        2.0 * p_val * r_val / sum
    }

    public func accuracy(_p: ArrayList<Int64>, _t: ArrayList<Int64>): Float64 {
        let total = this.true_positives + this.true_negatives +
                   this.false_positives + this.false_negatives
        let correct = this.true_positives + this.true_negatives
        if (total == 0L) { return 0.0 }
        Float64(correct) / Float64(total)
    }
}

import std.collection.ArrayList

class MetricsCalculator2 {

    public init() {}

    /* ---------- helpers ---------- */
    private static func _singleMrr(labels: ArrayList<Int64>, k: Int64): Float64 {
        for (i in 0..labels.size) {
            if (labels[i] == 1) {
                return 1.0 / (i + 1)
            }
        }
        return 0.0
    }

    private static func _singleMap(labels: ArrayList<Int64>, totalRelevant: Int64): Float64 {
        var precisions = ArrayList<Float64>()
        var foundRelevant = 0
        for (i in 0..labels.size) {
            if (labels[i] == 1) {
                foundRelevant += 1
                precisions.add(foundRelevant.float / (i + 1))
            }
        }
        if (precisions.size == 0) {
            return 0.0
        }
        var sum = 0.0
        for (p in precisions) { sum += p }
        return sum / totalRelevant
    }

    /* ---------- public ---------- */
    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        var mrrScores = ArrayList<Float64>()
        if (data is (ArrayList<Int64>, Int64)) {
            let (labels, _) = data as (ArrayList<Int64>, Int64)
            let score = _singleMrr(labels, labels.size)
            mrrScores.add(score)
            return (score, mrrScores)
        } else if (data is ArrayList<(ArrayList<Int64>, Int64)>) {
            let list = data as ArrayList<(ArrayList<Int64>, Int64)>
            for (item in list) {
                let (labels, _) = item
                mrrScores.add(_singleMrr(labels, labels.size))
            }
            var sum = 0.0
            for (v in mrrScores) { sum += v }
            return (sum / mrrScores.size, mrrScores)
        } else {
            return (0.0, mrrScores)
        }
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        var mapScores = ArrayList<Float64>()
        if (data is (ArrayList<Int64>, Int64)) {
            let (labels, total) = data as (ArrayList<Int64>, Int64)
            let score = _singleMap(labels, total)
            mapScores.add(score)
            return (score, mapScores)
        } else if (data is ArrayList<(ArrayList<Int64>, Int64)>) {
            let list = data as ArrayList<(ArrayList<Int64>, Int64)>
            for (item in list) {
                let (labels, total) = item
                mapScores.add(_singleMap(labels, total))
            }
            var sum = 0.0
            for (v in mapScores) { sum += v }
            return (sum / mapScores.size, mapScores)
        } else {
            return (0.0, mapScores)
        }
    }
}

import std.collection.ArrayList
import std.random.Random
import std.sort.*

class MinesweeperGame {
    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        // 1. 创建 n×n 的二维 ArrayList，初始全 '0'
        var grid = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            var row = ArrayList<String>()
            for (j in 0..n) {
                row.add("0")
            }
            grid.add(row)
        }

        // 2. 随机放置 k 个地雷
        let rng = Random()
        var placed = 0
        while (placed < k) {
            let x = rng.nextInt64(n)
            let y = rng.nextInt64(n)
            if (grid[x][y] == "X") { continue }
            grid[x][y] = "X"
            placed += 1
        }

        // 3. 更新周围 8 个方向的数字
        let dx = [-1, -1, -1, 0, 0, 1, 1, 1]
        let dy = [-1, 0, 1, -1, 1, -1, 0, 1]
        for (i in 0..n) {
            for (j in 0..n) {
                if (grid[i][j] == "X") { continue }
                var cnt = 0
                for (d in 0..8) {
                    let ni = i + dx[d]
                    let nj = j + dy[d]
                    if (ni >= 0 && ni < n && nj >= 0 && nj < n && grid[ni][nj] == "X") {
                        cnt += 1
                    }
                }
                grid[i][j] = String(cnt)
            }
        }
        return grid
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        var pm = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            var row = ArrayList<String>()
            for (j in 0..n) {
                row.add("-")
            }
            pm.add(row)
        }
        return pm
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for (i in 0..n) {
            for (j in 0..n) {
                if (map[i][j] == "-" && minesweeper_map[i][j] != "X") {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if (x < 0 || x >= n || y < 0 || y >= n) {
            return player_map
        }
        if (player_map[x][y] != "-") {
            return player_map
        }
        player_map[x][y] = minesweeper_map[x][y]
        if (minesweeper_map[x][y] == "X") {
            return false
        }
        if (check_won(player_map)) {
            return true
        }
        return player_map
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.time.DateTime
import std.math.*

class MovieBookingSystem {

    let movies: ArrayList<HashMap<String, Any>>

    public init() {
        movies = ArrayList<HashMap<String, Any>>()
    }

    public func add_movie(name: String, price: Float64, start_time: String, end_time: String, n: Int64): Unit {
        let seats = ArrayList<ArrayList<Int64>>()
        for (i in 0..n) {
            let row = ArrayList<Int64>()
            for (j in 0..n) {
                row.append(0)
            }
            seats.append(row)
        }
        let movieMap = HashMap<String, Any>()
        movieMap["name"] = name
        movieMap["price"] = price
        movieMap["start_time"] = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        movieMap["end_time"] = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")
        movieMap["seats"] = seats
        movies.append(movieMap)
    }

    public func book_ticket(name: String, seats_to_book: ArrayList<ArrayList<Int64>>): String {
        for (movie in movies) {
            let movieName = movie["name"] as String
            if (movieName == name) {
                let seats = movie["seats"] as ArrayList<ArrayList<Int64>>
                // Check availability
                for (seat in seats_to_book) {
                    let row = seat[0]
                    let col = seat[1]
                    if (row < 0 || row >= seats.size || col < 0 || col >= seats[row].size) {
                        return "Booking failed."
                    }
                    if (seats[row][col] != 0) {
                        return "Booking failed."
                    }
                }
                // Book seats
                for (seat in seats_to_book) {
                    let row = seat[0]
                    let col = seat[1]
                    seats[row][col] = 1
                }
                return "Booking success."
            }
        }
        return "Movie not found."
    }

    public func available_movies(start_time: String, end_time: String): ArrayList<String> {
        let start = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        let end = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")
        let result = ArrayList<String>()
        for (movie in movies) {
            let movieStart = movie["start_time"] as DateTime
            let movieEnd = movie["end_time"] as DateTime
            if (movieStart >= start && movieEnd <= end) {
                result.append(movie["name"] as String)
            }
        }
        return result
    }
}

import std.random.Random
import std.collection.ArrayList

class MusicPlayer {
    var playlist: ArrayList<String>
    var current_song: Option<String>
    var volume: Int64

    public init() {
        this.playlist = ArrayList<String>()
        this.current_song = None
        this.volume = 50
    }

    public func add_song(song: String): Unit {
        this.playlist.add(song)
    }

    public func remove_song(song: String): Unit {
        let index = this.playlist.indexOf(song)
        if (index >= 0) {
            this.playlist.remove(at: index)
            if (this.current_song == Some<String>(song)) {
                this.current_song = None
            }
        }
    }

    public func play(): Option<String> {
        if (this.playlist.size == 0) {
            return None
        }
        if (this.current_song is None) {
            this.current_song = Some<String>(this.playlist[0])
        }
        return this.current_song
    }

    public func stop(): Bool {
        if (this.current_song is Some<String>) {
            this.current_song = None
            return true
        }
        return false
    }

    public func switch_song(): Bool {
        if (this.playlist.size == 0 || this.current_song is None) {
            return false
        }
        let current = this.current_song.getOrThrow()
        let index = this.playlist.indexOf(current)
        let nextIndex = index + 1
        if (nextIndex < this.playlist.size) {
            this.current_song = Some<String>(this.playlist[nextIndex])
            return true
        }
        return false
    }

    public func previous_song(): Bool {
        if (this.playlist.size == 0 || this.current_song is None) {
            return false
        }
        let current = this.current_song.getOrThrow()
        let index = this.playlist.indexOf(current)
        let prevIndex = index - 1
        if (prevIndex >= 0) {
            this.current_song = Some<String>(this.playlist[prevIndex])
            return true
        }
        return false
    }

    public func set_volume(volume: Int64): Bool {
        if (volume >= 0 && volume <= 100) {
            this.volume = volume
            return true
        }
        return false
    }

    public func shuffle(): Bool {
        if (this.playlist.size == 0) {
            return false
        }
        let rng = Random()
        for (i in 0..this.playlist.size) {
            let j = rng.nextInt(this.playlist.size)
            let temp = this.playlist[i]
            this.playlist[i] = this.playlist[j]
            this.playlist[j] = temp
        }
        if (this.current_song is Some<String>) {
            this.current_song = Some<String>(this.playlist[0])
        }
        return true
    }
}

