import std.collection.*
import std.regex.Regex
import std.sort.*

class NLPDataProcessor2 {
    // helper: clean one string → lower-case word list
    private func cleanAndSplit(s: String): ArrayList<String> {
        // keep only a-z/A-Z and spaces
        let re = Regex("[^a-zA-Z ]")
        let cleaned = re.replaceAll(s, "")
        let words = ArrayList<String>()
        for (w in cleaned.split(" ")) {
            if (w.size > 0) { words.add(w.lowercase()) }
        }
        return words
    }

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let out = ArrayList<ArrayList<String>>()
        for (line in string_list) {
            out.add(cleanAndSplit(line))
        }
        return out
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        let freq = HashMap<String, Int64>()
        for (lst in words_list) {
            for (w in lst) {
                let old = freq.get(w) ?? 0
                freq.add(w, old + 1)
            }
        }
        // sort by descending frequency
        let entries = ArrayList<(String, Int64)>()
        freq.foreach{ k: String, v: Int64 => entries.add((k, v)) }
        let cmp = { l: (String, Int64), r: (String, Int64) => l[1] < r[1] }
        sort(entries, lessThan: cmp, descending: true)

        // keep top 5
        let top = HashMap<String, Int64>()
        for (i in 0..min(5, entries.size)) {
            let (k, v) = entries[i]
            top.add(k, v)
        }
        return top
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        let words = process_data(string_list)
        return calculate_word_frequency(words)
    }
}

import std.convert.Formattable
import std.convert.Parsable
import std.convert.RadixConvertible

class NumberConverter {

    public static func decimal_to_binary(decimal_num: Int64): String {
        if (decimal_num == 0) {
            return "0"
        }
        var n = decimal_num
        var res = ""
        while (n > 0) {
            res = "${n % 2}${res}"
            n = n / 2
        }
        return res
    }

    public static func binary_to_decimal(binary_num: String): Int64 {
        var res: Int64 = 0
        for (c in binary_num.runes()) {
            res = res * 2 + (Int64(c) - Int64(r'0'))
        }
        return res
    }

    public static func decimal_to_octal(decimal_num: Int64): String {
        if (decimal_num == 0) {
            return "0"
        }
        var n = decimal_num
        var res = ""
        while (n > 0) {
            res = "${n % 8}${res}"
            n = n / 8
        }
        return res
    }

    public static func octal_to_decimal(octal_num: String): Int64 {
        var res: Int64 = 0
        for (c in octal_num.runes()) {
            res = res * 8 + (Int64(c) - Int64(r'0'))
        }
        return res
    }

    public static func decimal_to_hex(decimal_num: Int64): String {
        if (decimal_num == 0) {
            return "0"
        }
        var n = decimal_num
        var res = ""
        while (n > 0) {
            let rem = n % 16
            let digit = if (rem < 10) {
                "${rem}"
            } else {
                Rune(rem - 10 + Int64(r'a')).toString()
            }
            res = "${digit}${res}"
            n = n / 16
        }
        return res
    }

    public static func hex_to_decimal(hex_num: String): Int64 {
        var res: Int64 = 0
        for (c in hex_num.runes()) {
            let v = if (c >= r'0' && c <= r'9') {
                Int64(c) - Int64(r'0')
            } else if (c >= r'a' && c <= r'f') {
                Int64(c) - Int64(r'a') + 10
            } else if (c >= r'A' && c <= r'F') {
                Int64(c) - Int64(r'A') + 10
            } else {
                0
            }
            res = res * 16 + v
        }
        return res
    }
}

import std.collection.*
import std.convert.*

class NumberWordFormatter {

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>

    public init() {
        this.NUMBER      = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN",
                            "SIXTEEN", "SEVENTEEN", "EIGHTEEN", "NINETEEN"]
        this.NUMBER_TEN  = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
    }

    public func format(x: Option<String>): String {
        match (x) {
            case None<String> => "ZERO ONLY"
            case Some<String>(v) => format_string(v)
        }
    }

    public func format_string(x: String): String {
        let s = x.replace(",", "")
        let parts = s.split(".", 2)
        let intPart = parts[0]
        let decPart = if (parts.size == 2) { parts[1] } else { "" }

        var res = ""
        if (intPart == "0") {
            res = "ZERO"
        } else {
            res = trans_integer(intPart)
        }

        if (decPart.size > 0) {
            res += " POINT " + trans_decimal(decPart)
        }
        res + " ONLY"
    }

    func trans_integer(s: String): String {
        let digits = s.toRuneArray().map({r: Rune => (r.toInt() - 48).toInt64()})
        let pad = 3 - (digits.size % 3)
        let padded = if (pad == 3) { digits } else {
            Array<Int64>(ArrayList<Int64>().also({it =>
                for (_ in 0..pad) { it.add(0) }
                for (d in digits) { it.add(d) }
            }))
        }
        var groups = ArrayList<Array<Int64>>()
        for (i in 0..padded.size by 3) {
            if (i + 2 < padded.size) {
                groups.add([padded[i], padded[i+1], padded[i+2]])
            }
        }

        var buf = ArrayList<String>()
        for (i in 0..groups.size) {
            let g = groups[groups.size - 1 - i]
            if (g[0] == 0 && g[1] == 0 && g[2] == 0) { continue() }
            let t = trans_three(g.map({d: Int64 => ('0'.toInt() + d).toRune()}).toRuneArray().toString())
            let suffix = parse_more(i.toInt64())
            buf.add(t + (if (suffix.size > 0) { " " + suffix } else { "" }))
        }
        buf.toArray().join(" ")
    }

    func trans_decimal(s: String): String {
        let runes = s.toRuneArray()
        var out = ""
        for (r in runes) {
            let d = r.toInt() - 48
            out += NUMBER[d] + " "
        }
        out.trimEnd()
    }

    public func trans_two(s: String): String {
        let n = Int64.parse(s)
        if (n < 10) {
            NUMBER[n]
        } else if (n < 20) {
            NUMBER_TEEN[n - 10]
        } else {
            let ten = n / 10
            let one = n % 10
            if (one == 0) {
                NUMBER_TEN[ten - 1]
            } else {
                NUMBER_TEN[ten - 1] + " " + NUMBER[one]
            }
        }
    }

    public func trans_three(s: String): String {
        let runes = s.toRuneArray()
        let a = (runes[0].toInt() - 48).toInt64()
        let rest = runes.slice(1, 3).toRuneArray().toString()
        var res = ""
        if (a > 0) {
            res = NUMBER[a] + " HUNDRED"
            if (rest != "00") {
                res += " AND " + trans_two(rest)
            }
        } else {
            trans_two(rest)
        }
        res
    }

    public func parse_more(i: Int64): String {
        if (i >= 0 && i < NUMBER_MORE.size) {
            NUMBER_MORE[i]
        } else {
            ""
        }
    }
}

import std.collection.ArrayList
import std.convert.RadixConvertible

class NumericEntityUnescaper {
    public init() {}

    public func replace(string: String): String {
        let chars = string.toRuneArray()
        let res   = ArrayList<Rune>()
        let n     = chars.size
        var i     = 0

        while (i < n) {
            if (chars[i] == r'&' && i + 2 < n && chars[i + 1] == r'#') {
                var base = 10
                var j    = i + 2
                if (chars[j] == r'x' || chars[j] == r'X') {
                    base = 16
                    j += 1
                }
                var value = 0
                while (j < n && chars[j] != r';') {
                    let c = chars[j]
                    var digit = -1
                    if (c >= r'0' && c <= r'9') {
                        digit = (c - r'0').toInt64()
                    } else if (base == 16) {
                        if (c >= r'a' && c <= r'f') {
                            digit = (c - r'a' + 10).toInt64()
                        } else if (c >= r'A' && c <= r'F') {
                            digit = (c - r'A' + 10).toInt64()
                        }
                    }
                    if (digit < 0) { break }
                    value = value * base + digit
                    j += 1
                }
                if (j < n && chars[j] == r';' && j > i + 2) {
                    res.add(Rune(value))
                    i = j + 1
                    continue
                }
            }
            res.add(chars[i])
            i += 1
        }
        String.fromRuneArray(res.toArray())
    }

    public static func is_hex_char(char: Rune): Bool {
        (char >= r'0' && char <= r'9') ||
        (char >= r'a' && char <= r'f') ||
        (char >= r'A' && char <= r'F')
    }
}

