    let sex: Option<String>
    let phoneNumber: Option<String>

    public init(name: String, sex: String, phoneNumber: String) {
        this.name = _validate_name(name) 
        this.sex = _validate_sex(sex)
        this.phoneNumber = _validate_phoneNumber(phoneNumber)
    }

    public static func _validate_name(name: String): Option<String> {
        if (name.size == 0 || name.size > 33) {
            return None<String>
        }
        return Some<String>(name)
    }

    public static func _validate_sex(sex: String): Option<String> {
        let valid = HashSet<String>(["Man", "Woman", "UGM"])
        if (valid.contains(sex)) {
            return Some<String>(sex)
        }
        return None<String>
    }

    public static func _validate_phoneNumber(phoneNumber: String): Option<String> {
        if (phoneNumber.size != 11) {
            return None<String>
        }
        for (ch in phoneNumber.runes()) {
            if (ch < r'0' || ch > r'9') {
                return None<String>
            }
        }
        return Some<String>(phoneNumber)
    }
}

import std.collection.ArrayList

class PushBoxGame {

    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for (i in 0..map.size) {
                for (j in 0..map[i].size) {
                    let cell = map[i][j]
                    if (cell == "O") {
                        this.player_row = i
                        this.player_col = j
                        this.map[i][j] = " "
                    } else if (cell == "G") {
                        this.targets.add(ArrayList<Int64>([i, j]))
                        this.target_count += 1
                        this.map[i][j] = " "
                    } else if (cell == "X") {
                        this.boxes.add(ArrayList<Int64>([i, j]))
                        this.map[i][j] = " "
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        var onTarget = 0
        for (b in this.boxes) {
            for (t in this.targets) {
                if (b[0] == t[0] && b[1] == t[1]) {
                    onTarget += 1
                    break
                }
            }
        }
        this.is_game_over = (onTarget == this.target_count)
        this.is_game_over
    }

    public func move(direction: String): Bool {
        let dr = direction == "w" ? -1 : (direction == "s" ? 1 : 0)
        let dc = direction == "a" ? -1 : (direction == "d" ? 1 : 0)
        let nr = this.player_row + dr
        let nc = this.player_col + dc

        if (this.map[nr][nc] == "#") {
            return this.check_win()
        }

        // check if a box is in the way
        var boxIdx: Int64 = -1
        for (i in 0..this.boxes.size) {
            if (this.boxes[i][0] == nr && this.boxes[i][1] == nc) {
                boxIdx = i
                break
            }
        }

        if (boxIdx >= 0) {
            let br = nr + dr
            let bc = nc + dc
            if (this.map[br][bc] == "#") {
                return this.check_win()
            }
            // another box?
            for (b in this.boxes) {
                if (b[0] == br && b[1] == bc) {
                    return this.check_win()
                }
            }
            // move box
            this.boxes[boxIdx][0] = br
            this.boxes[boxIdx][1] = bc
        }

        // move player
        this.player_row = nr
        this.player_col = nc
        this.check_win()
    }
}

import std.regex.Regex
import std.collection.ArrayList
import std.sort.*

class RegexUtils {

    public func match_regex(pattern: String, text: String): Bool {
        let re = Regex(pattern)
        return re.isMatch(text)
    }

    public func findall(pattern: String, text: String): ArrayList<String> {
        let re = Regex(pattern)
        let matches = re.findAll(text)
        let res = ArrayList<String>()
        for (m in matches) {
            res.add(m.group(0))
        }
        return res
    }

    public func split(pattern: String, text: String): ArrayList<String> {
        let re = Regex(pattern)
        let parts = re.split(text)
        let res = ArrayList<String>()
        for (p in parts) {
            res.add(p)
        }
        return res
    }

    public func sub(pattern: String, replacement: String, text: String): String {
        let re = Regex(pattern)
        return re.replaceAll(text, replacement)
    }

    public func generate_email_pattern(): String {
        return r"\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b"
    }

    public func generate_phone_number_pattern(): String {
        return r"\b\d{3}-\d{3}-\d{4}\b"
    }

    public func generate_split_sentences_pattern(): String {
        return r"[.!?][\s]{1,2}(?=[A-Z])"
    }

    public func split_sentences(text: String): ArrayList<String> {
        let pattern = generate_split_sentences_pattern()
        let re = Regex(pattern)
        let parts = re.split(text)
        let res = ArrayList<String>()
        for (p in parts) {
            res.add(p.trim())
        }
        return res
    }

    public func validate_phone_number(phone_number: String): Bool {
        let pattern = generate_phone_number_pattern()
        return match_regex(pattern, phone_number)
    }

    public func extract_email(text: String): ArrayList<String> {
        let pattern = generate_email_pattern()
        return findall(pattern, text)
    }
}

class RPGCharacter {
    let name: String
    var hp: Int64
    var attack_power: Int64
    var defense: Int64
    var level: Int64
    var exp: Int64

    public init(name: String, hp: Int64, attack_power: Int64, defense: Int64, level!: Int64 = 1) {
        this.name = name
        this.hp = hp
        this.attack_power = attack_power
        this.defense = defense
        this.level = level
        this.exp = 0
    }

    public func attack(other_character: RPGCharacter): Unit {
        let damage = this.attack_power - other_character.defense
        let actualDamage = if (damage > 0) { damage } else { 0 }
        other_character.hp -= actualDamage
    }

    public func heal(): Int64 {
        this.hp = if (this.hp + 10 > 100) { 100 } else { this.hp + 10 }
        return this.hp
    }

    public func gain_exp(amount: Int64): Unit {
        var remaining = amount
        while (remaining > 0) {
            let needed = this.level * 100 - this.exp
            if (remaining >= needed) {
                this.level_up()
                remaining -= needed
            } else {
                this.exp += remaining
                break
            }
        }
    }

    public func level_up(): (Int64, Int64, Int64, Int64) {
        if (this.level < 100) {
            this.level += 1
            this.hp += 20
            this.attack_power += 5
            this.defense += 5
            this.exp = 0
        }
        return (this.level, this.hp, this.attack_power, this.defense)
    }

    public func is_alive(): Bool {
        return this.hp > 0
    }
}

