class ShoppingCart {
    let items: HashMap<String, Item>

    public init() {
        items = HashMap<String, Item>()
    }

    public func add_item(item: String, price: Float64, quantity!: Int64 = 1): Unit {
        if (items.contains(item)) {
            let old = items[item]
            items[item] = Item(price, old.quantity + quantity)
        } else {
            items[item] = Item(price, quantity)
        }
    }

    public func remove_item(item: String, quantity!: Int64 = 1): Unit {
        if (items.contains(item)) {
            let old = items[item]
            let newQty = old.quantity - quantity
            if (newQty <= 0) {
                items.remove(item)
            } else {
                items[item] = Item(old.price, newQty)
            }
        }
    }

    public func view_items(): HashMap<String, Item> {
        return items
    }

    public func total_price(): Float64 {
        var sum: Float64 = 0.0
        for (kv in items) {
            let (name, it) = kv
            sum = sum + it.price * Float64(it.quantity)
        }
        return sum
    }
}

