import std.collection.ArrayList
import std.random.Random

class Snake {
    var length: Int64
    let SCREEN_WIDTH: Int64
    let SCREEN_HEIGHT: Int64
    let BLOCK_SIZE: Int64
    var positions: ArrayList<ArrayList<Int64>>
    var score: Int64
    var food_position: ArrayList<Int64>

    public init(SCREEN_WIDTH: Int64, SCREEN_HEIGHT: Int64, BLOCK_SIZE: Int64, food_position: ArrayList<Int64>) {
        this.length = 1
        this.SCREEN_WIDTH = SCREEN_WIDTH
        this.SCREEN_HEIGHT = SCREEN_HEIGHT
        this.BLOCK_SIZE = BLOCK_SIZE
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2])])
        this.score = 0
        this.food_position = food_position
    }

    public func move(direction: ArrayList<Int64>): Unit {
        let head = this.positions[0]
        let newX = head[0] + direction[0] * this.BLOCK_SIZE
        let newY = head[1] + direction[1] * this.BLOCK_SIZE
        let newHead = ArrayList<Int64>([newX, newY])

        // Check self-collision
        for (pos in this.positions) {
            if (pos[0] == newHead[0] && pos[1] == newHead[1]) {
                this.reset()
                return
            }
        }

        this.positions.add(newHead, at: 0)

        // Check food collision
        if (newHead[0] == this.food_position[0] && newHead[1] == this.food_position[1]) {
            this.eat_food()
        } else {
            this.positions.remove(at: this.positions.size - 1)
        }
    }

    public func random_food_position(): Unit {
        let rand = Random()
        var x: Int64 = 0
        var y: Int64 = 0
        var overlap = true

        while (overlap) {
            x = (rand.nextInt64() % (this.SCREEN_WIDTH / this.BLOCK_SIZE)) * this.BLOCK_SIZE
            y = (rand.nextInt64() % (this.SCREEN_HEIGHT / this.BLOCK_SIZE)) * this.BLOCK_SIZE
            overlap = false
            for (pos in this.positions) {
                if (pos[0] == x && pos[1] == y) {
                    overlap = true
                    break
                }
            }
        }
        this.food_position = ArrayList<Int64>([x, y])
    }

    public func reset(): Unit {
        this.length = 1
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([this.SCREEN_WIDTH / 2, this.SCREEN_HEIGHT / 2])])
        this.score = 0
        this.random_food_position()
    }

    public func eat_food(): Unit {
        this.length += 1
        this.score += 100
        this.random_food_position()
    }
}

import std.collection.ArrayList
import std.regex.Regex

class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        // Match sentences that end with . or ? followed by a space, but exclude "Mr."
        let re = Regex("(?<!Mr)(?:[.?](?=\\s))")
        let parts = re.split(sentences_string)
        let result = ArrayList<String>()
        for (part in parts) {
            let trimmed = part.trim()
            if (trimmed.size > 0) {
                // Append the delimiter back to the sentence
                let end = Regex("[.?]$").find(trimmed)
                if (end == None) {
                    // Re-append the delimiter from the original string
                    let next = re.findAt(sentences_string, trimmed.size + 1)
                    let delim = if (next != None) { next.get().group(0) } else { "" }
                    result.add("${trimmed}${delim}")
                } else {
                    result.add(trimmed)
                }
            }
        }
        return result
    }

    public func count_words(sentence: String): Int64 {
        let words = Regex("[a-zA-Z]+").findAll(sentence)
        return words.size
    }

    public func process_text_file(sentences_string: String): Int64 {
        let sentences = split_sentences(sentences_string)
        var maxWords: Int64 = 0
        for (s in sentences) {
            let cnt = count_words(s)
            if (cnt > maxWords) {
                maxWords = cnt
            }
        }
        return maxWords
    }
}

