        let vals = ArrayList<String>()
        for (kv in data) {
            keys.add(kv.0)
            vals.add("'${kv.1}'")
        }
        let kstr = keys.join(", ")
        let vstr = vals.join(", ")
        "INSERT INTO ${this.table_name} (${kstr}) VALUES (${vstr});"
