        let sets = ArrayList<String>()
        for (kv in data) {
            sets.add("${kv.0} = '${kv.1}'")
        }
        let setstr = sets.join(", ")
        "UPDATE ${this.table_name} SET ${setstr} WHERE ${condition};"
    }

