        if (where_condition is Some<HashMap<String, String>>) {
            sb.append(" WHERE ")
            let cond = (where_condition as Some<HashMap<String, String>>).getOrThrow()
            let parts = ArrayList<String>()
            for (kv in cond) {
                parts.add("${kv[0]}='${kv[1]}'")
            }
            sb.append(parts.join(" AND "))
        }
        return sb.toString()
    }

