import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        let n = data.size
        if (n == 0) {
            return 0.0
        }
        var sorted = ArrayList<Int64>(data)
        sort(sorted)
        if (n % 2 == 1) {
            return Float64(sorted[n / 2])
        } else {
            return (Float64(sorted[n / 2 - 1]) + Float64(sorted[n / 2])) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let freq = HashMap<Int64, Int64>()
        for (x in data) {
            freq[x] = freq.get(x) ?? 0 + 1
        }
        var maxCount = 0
        for (kv in freq) {
            if (kv.1 > maxCount) {
                maxCount = kv.1
            }
        }
        let modes = ArrayList<Int64>()
        for (kv in freq) {
            if (kv.1 == maxCount) {
                modes.add(kv.0)
            }
        }
        sort(modes)
        return modes
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        let n = data.size
        if (n == 0) {
            return None<Float64>
        }
        var sum: Int64 = 0
        for (x in data) {
            sum = sum + x
        }
        return Some<Float64>(Float64(sum) / Float64(n))
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let mOpt = mean(data)
        if (mOpt is None) {
            return None<Float64>
        }
        let m = mOpt.getOrThrow()
        let n = data.size
        var sumSq: Float64 = 0.0
        for (x in data) {
            let diff = Float64(x) - m
            sumSq = sumSq + diff * diff
        }
        return Some<Float64>(sqrt(sumSq / Float64(n)))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let mOpt = mean(data)
        let sdOpt = standard_deviation(data)
        if (mOpt is None || sdOpt is None) {
            return None<ArrayList<Float64>>
        }
        let m = mOpt.getOrThrow()
        let sd = sdOpt.getOrThrow()
        if (sd == 0.0) {
            return None<ArrayList<Float64>>
        }
        let res = ArrayList<Float64>()
        for (x in data) {
            res.add((Float64(x) - m) / sd)
        }
        return Some<ArrayList<Float64>>(res)
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        let n = x.size
        if (n != y.size || n == 0) {
            return None<Float64>
        }
        var sx: Float64 = 0.0
        var sy: Float64 = 0.0
        var sxx: Float64 = 0.0
        var syy: Float64 = 0.0
        var sxy: Float64 = 0.0
        for (i in 0..n) {
            let xi = Float64(x[i])
            let yi = Float64(y[i])
            sx = sx + xi
            sy = sy + yi
            sxx = sxx + xi * xi
            syy = syy + yi * yi
            sxy = sxy + xi * yi
        }
        let num = Float64(n) * sxy - sx * sy
        let den = sqrt((Float64(n) * sxx - sx * sx) * (Float64(n) * syy - sy * sy))
        if (den == 0.0) {
            return None<Float64>
        }
        return Some<Float64>(num / den)
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let k = data.size
        let mat = ArrayList<ArrayList<Float64>>()
        for (i in 0..k) {
            let row = ArrayList<Float64>()
            for (j in 0..k) {
                let cOpt = correlation(data[i], data[j])
                row.add(cOpt ?? 0.0)
            }
            mat.add(row)
        }
        return mat
    }
}

