class Thermostat {
    var current_temperature: Float64
    var target_temperature: Float64
    var mode: String

    public init(current_temperature: Float64, target_temperature: Float64, mode: String) {
        this.current_temperature = current_temperature
        this.target_temperature = target_temperature
        this.mode = mode
    }

    public func get_target_temperature(): Float64 {
        this.target_temperature
    }

    public func set_target_temperature(temperature: Float64): Unit {
        this.target_temperature = temperature
    }

    public func get_mode(): String {
        this.mode
    }

    public func set_mode(mode: String): Bool {
        if (mode == "heat" || mode == "cool") {
            this.mode = mode
            true
        } else {
            false
        }
    }

    public func auto_set_mode(): Unit {
        if (this.current_temperature < this.target_temperature) {
            this.mode = "heat"
        } else {
            this.mode = "cool"
        }
    }

    public func auto_check_conflict(): Bool {
        let conflict = (this.mode == "heat" && this.current_temperature > this.target_temperature) ||
                       (this.mode == "cool" && this.current_temperature < this.target_temperature)
        if (conflict) {
            this.auto_set_mode()
            false
        } else {
            true
        }
    }

    public func simulate_operation(): Int64 {
        this.auto_set_mode()
        var time: Int64 = 0
        while (abs(this.current_temperature - this.target_temperature) > 0.01) {
            if (this.mode == "heat") {
                this.current_temperature += 0.5
            } else {
                this.current_temperature -= 0.5
            }
            time += 1
        }
        time
    }
}

import std.collection.ArrayList

class TicTacToe {

    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(N!: Int64 = 3) {
        this.board = ArrayList<ArrayList<String>>()
        for (_ in 0..N) {
            let row = ArrayList<String>()
            for (_ in 0..N) {
                row.add(" ")
            }
            this.board.add(row)
        }
        this.current_player = "X"
    }

    public func make_move(row: Int64, col: Int64): Bool {
        if (row < 0 || row >= board.size || col < 0 || col >= board[0].size) {
            return false
        }
        if (board[row][col] != " ") {
            return false
        }
        board[row][col] = current_player
        current_player = if (current_player == "X") { "O" } else { "X" }
        return true
    }

    public func check_winner(): Option<String> {
        let N = board.size
        // rows
        for (r in 0..N) {
            let first = board[r][0]
            if (first == " ") { continue }
            var win = true
            for (c in 1..N) {
                if (board[r][c] != first) { win = false; break }
            }
            if (win) { return Some<String>(first) }
        }
        // columns
        for (c in 0..N) {
            let first = board[0][c]
            if (first == " ") { continue }
            var win = true
            for (r in 1..N) {
                if (board[r][c] != first) { win = false; break }
            }
            if (win) { return Some<String>(first) }
        }
        // diagonals
        let first1 = board[0][0]
        if (first1 != " ") {
            var win = true
            for (i in 1..N) {
                if (board[i][i] != first1) { win = false; break }
            }
            if (win) { return Some<String>(first1) }
        }
        let first2 = board[0][N - 1]
        if (first2 != " ") {
            var win = true
            for (i in 1..N) {
                if (board[i][N - 1 - i] != first2) { win = false; break }
            }
            if (win) { return Some<String>(first2) }
        }
        None<String>
    }

    public func is_board_full(): Bool {
        for (row in board) {
            for (cell in row) {
                if (cell == " ") { return false }
            }
        }
        true
    }
}

