class TriCalculator {
    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        return taylor(x, 50)
    }

    public func factorial(a: Int64): Decimal {
        var res = Decimal(1)
        for (i in 1..a+1) {
            res = res * Decimal(i)
        }
        return res
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        let rad = x / 180.0 * PI
        var sum = 0.0
        for (k in 0..n) {
            let sign = (k % 2 == 0) ? 1.0 : -1.0
            let num = sign * (rad ** (2 * k))
            let den = factorial(2 * k)
            sum += Float64(num / den)
        }
        return sum
    }

    public func sin(x: Float64): Float64 {
        let rad = x / 180.0 * PI
        var sum = 0.0
        for (k in 0..50) {
            let sign = (k % 2 == 0) ? 1.0 : -1.0
            let num = sign * (rad ** (2 * k + 1))
            let den = factorial(2 * k + 1)
            sum += Float64(num / den)
        }
        return sum
    }

    public func tan(x: Float64): Option<Float64> {
        let c = cos(x)
        if (abs(c - 0.0) < 0.000001) {
            return None<Float64>
        }
        return Some<Float64>(sin(x) / c)
    }
}

