/* ---------- Parser (unchanged) ---------- */
class Parser {
    let expr: String
    var pos: Int64
    var ch: Rune

    public init(expr: String) {
        this.expr = expr
        this.pos = -1
        this.ch = r'x'
        this.next_char()
    }

    public func next_char(): Unit {
        this.pos += 1
        if (this.pos < this.expr.size) {
            this.ch = Rune(this.expr[this.pos])
        } else {
            this.ch = r'x'
        }
    }

    public func eat(char_to_eat: Rune): Bool {
        while (this.ch == r' ') {
            this.next_char()
        }
        if (this.ch == char_to_eat) {
            this.next_char()
            return true
        }
        return false
    }

    public func parse(): Int64 {
        let x = this.parse_expression()
        if (this.pos < this.expr.size) {
            throw Exception("Unexpected: ${this.ch}")
        }
        return x
    }

    public func parse_expression(): Int64 {
        var x = this.parse_term()
        while (true) {
            if (this.eat(r'+')) {
                x += this.parse_term()
            } else if (this.eat(r'-')) {
                x -= this.parse_term()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_term(): Int64 {
        var x = this.parse_factor()
        while (true) {
            if (this.eat(r'*')) {
                x *= this.parse_factor()
            } else if (this.eat(r'/')) {
                x /= this.parse_factor()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_factor(): Int64 {
        if (this.eat(r'+')) {
            return this.parse_factor()
        }
        if (this.eat(r'-')) {
            return -this.parse_factor()
        }

        var x = 0
        var start_pos = this.pos

        if (this.eat(r'(')) {
            x = this.parse_expression()
            this.eat(r')')
        } else if (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
            while (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
                this.next_char()
            }
            x = Int64.parse(this.expr[start_pos..this.pos])
        } else {
            if (this.ch != r'x') {
                throw Exception("Unexpected: ${this.ch}")
            } else {
                throw Exception("Unexpected end of expression")
            }
        }
        return x
    }
}

/* ---------- Twenty-Four Point Game ---------- */
class TwentyFourPointGame {
    var nums: ArrayList<Int64>

    public init() {
        this.nums = ArrayList<Int64>()
    }

    private func _generate_cards(): Unit {
        this.nums.clear()
        let rng = Random()
        for (_ in 0..4) {
            this.nums.add(rng.nextInt(1, 10))
        }
    }

    public func get_my_cards(): ArrayList<Int64> {
        this._generate_cards()
        return this.nums
    }

    private func _count_cards_used(expr: String, cards: ArrayList<Int64>): Bool {
        var cnt = HashMap<Int64, Int64>()
        for (c in cards) {
            cnt[c] = (cnt.get(c) ?? 0) + 1
        }

        var i = 0
        while (i < expr.size) {
            let ch = Rune(expr[i])
            if (ch.isAsciiNumber()) {
                var j = i
                while (j < expr.size && Rune(expr[j]).isAsciiNumber()) {
                    j += 1
                }
                let num = Int64.parse(expr[i..j])
                let expected = cnt.get(num) ?? 0
                if (expected == 0) {
                    return false
                }
                cnt[num] = expected - 1
                i = j
            } else {
                i += 1
            }
        }

        for (v in cnt.values) {
            if (v != 0) {
                return false
            }
        }
        return true
    }

    public func evaluate_expression(expression: String): Bool {
        let parser = Parser(expression)
        let res = parser.parse()
        return res == 24
    }

    public func answer(expression: String): Bool {
        if (!this._count_cards_used(expression, this.nums)) {
            return false
        }
        return this.evaluate_expression(expression)
    }
}

import std.collection.HashMap
