class URLHandler {

    let url: String

    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let m = Regex("^(https?)://").find(url)
        if (m.isSome()) {
            return Some<String>(m.get().group(1).getOrThrow())
        }
        return None<String>
    }

    public func get_host(): Option<String> {
        let m = Regex("^(https?)://([^/]+)").find(url)
        if (m.isSome()) {
            return Some<String>(m.get().group(2).getOrThrow())
        }
        return None<String>
    }

    public func get_path(): Option<String> {
        let m = Regex("^(https?)://[^/]+(/[^?#]*)").find(url)
        if (m.isSome()) {
            return Some<String>(m.get().group(2).getOrThrow())
        }
        return None<String>
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let m = Regex("\\?([^#]*)").find(url)
        if (m.isNone()) {
            return None<HashMap<String, String>>
        }
        let query = m.get().group(1).getOrThrow()
        let map = HashMap<String, String>()
        for (part in query.split("&")) {
            let kv = part.split("=")
            if (kv.size == 2) {
                map.add(kv[0], kv[1])
            }
        }
        return Some<HashMap<String, String>>(map)
    }

    public func get_fragment(): Option<String> {
        let m = Regex("#(.+)$").find(url)
        if (m.isSome()) {
            return Some<String>(m.get().group(1).getOrThrow())
        }
        return None<String>
    }
}

import std.collection.ArrayList

class UrlPath {

    let segments: ArrayList<String>
    var with_end_tag: Bool

    public init() {
        this.segments = ArrayList<String>()
        this.with_end_tag = false
    }

    public func add(segment: String): Unit {
        this.segments.add(segment)
    }

    public func parse(path: String): Unit {
        let fixed = UrlPath.fix_path(path)
        if (fixed.size == 0) {
            return
        }
        let parts = fixed.split("/")
        for (part in parts) {
            this.segments.add(part)
        }
    }

    public static func fix_path(path: String): String {
        var s = path
        while (s.size > 0 && s[0] == '/') {
            s = s[1..]
        }
        while (s.size > 0 && s[s.size - 1] == '/') {
            s = s[0..(s.size - 1)]
        }
        return s
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.math.abs
import std.math.sqrt
import std.math.log
import std.math.pow

class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        if (vector_1.size != vector_2.size) {
            return 0.0
        }
        var dotProduct: Float64 = 0.0
        var norm1: Float64 = 0.0
        var norm2: Float64 = 0.0
        for (i in 0..vector_1.size) {
            let x = vector_1[i]
            let y = vector_2[i]
            dotProduct += x * y
            norm1 += x * x
            norm2 += y * y
        }
        let denom = sqrt(norm1) * sqrt(norm2)
        if (denom == 0.0) {
            return 0.0
        }
        return dotProduct / denom
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for (v in vectors_all) {
            result.add(similarity(vector_1, v))
        }
        return result
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        if (vector_list_1.size != vector_list_2.size || vector_list_1.size == 0) {
            return 0.0
        }
        var dotSum: Float64 = 0.0
        var norm1Sum: Float64 = 0.0
        var norm2Sum: Float64 = 0.0
        for (i in 0..vector_list_1.size) {
            let v1 = vector_list_1[i]
            let v2 = vector_list_2[i]
            for (j in 0..v1.size) {
                let x = v1[j]
                let y = v2[j]
                dotSum += x * y
                norm1Sum += x * x
                norm2Sum += y * y
            }
        }
        let denom = sqrt(norm1Sum) * sqrt(norm2Sum)
        if (denom == 0.0) {
            return 0.0
        }
        return dotSum / denom
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let result = HashMap<String, Float64>()
        for (key in number_dict) {
            let count = number_dict[key]!
            let weight = log(Float64(total_num + 1) / (count + 1.0))
            result.add(key, weight)
        }
        return result
    }
}

